// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 fuzzValue) public {
        vm.assume(fuzzValue > 0 && fuzzValue <= address(this).balance);
        uint256 startCount = c.depositsCount();
        vm.deal(address(this), fuzzValue);
        (bool ok, ) = address(c).call{value: fuzzValue}("");
        require(ok, "call failed");
        uint256 endCount = c.depositsCount();
        assertTrue(endCount == startCount + 1);
    }
}
